use super::*;
fn fixture()->(Store,PathBuf,String,String,String){let root=crate::save_core::project().join("tests/work/m4").join(format!("chat-{}",uuid()));fs::create_dir_all(&root).unwrap();let mut s=Store::open_synthetic(&root,16384).unwrap();let(doc,rev)=s.create_document("chat-synthetic",&"a".repeat(64),30,"会话合成.pdf").unwrap();let conv=s.local_conversation(&doc).unwrap();(s,root,doc,rev,conv)}
fn metadata()->MessageMetadata{MessageMetadata{provider:Some("mock".into()),model:Some("mock-local".into()),preset_version:None,request_id:Some(uuid()),sent_context_hash:None,slot:None}}
fn turn(s:&mut Store,conv:&str,rev:&str,text:&str,parent:Option<&str>,edit:Option<&str>)->(String,String){let meta=metadata();let pair=s.ai_begin(conv,rev,text,parent,edit,&meta,"[]",1).unwrap();s.ai_append(conv,&pair.1,meta.request_id.as_deref().unwrap(),0,"合成回复").unwrap();s.ai_finish(conv,&pair.1,"complete",&serde_json::json!({"mock":true})).unwrap();pair}
fn path(s:&Store,conv:&str)->Vec<String>{s.chat_view(conv).unwrap().path.iter().map(|m|m.id.clone()).collect()}
#[test]fn chat_view_switches_exact_context_and_model_with_the_selected_version(){
 let(mut s,root,doc,rev,conv)=fixture();let make=|s:&mut Store,text:&str,edit:Option<&str>,model:&str,page:u32|{let mut meta=metadata();meta.model=Some(model.into());let context=serde_json::json!([{"id":"S1","grantId":"synthetic","name":"合成页.pdf","page":page,"text":text,"image":false,"documentId":doc,"reasons":["manual"]}]);let(u,a)=s.ai_begin(&conv,&rev,text,None,edit,&meta,&context.to_string(),page).unwrap();s.ai_append(&conv,&a,meta.request_id.as_deref().unwrap(),0,"Mock回答").unwrap();s.ai_finish(&conv,&a,"complete",&serde_json::json!({"mock":true})).unwrap();(u,a)};
 let(old,old_answer)=make(&mut s,"旧源",None,"mock-old",1);let(_,new_answer)=make(&mut s,"新源",Some(&old),"mock-new",9);
 for(answer,model,page)in [(&old_answer,"mock-old",1),(&new_answer,"mock-new",9)]{let view=s.chat_select(&conv,Some(answer)).unwrap();let selected=view.path.last().unwrap();assert_eq!(&selected.id,answer);assert_eq!(selected.metadata.model.as_deref(),Some(model));assert_eq!(s.ai_details(&conv,answer).unwrap()["sources"][0]["page"],page);}
 drop(s);let s=Store::open_synthetic(&root,16384).unwrap();let view=s.chat_view(&conv).unwrap();assert_eq!(view.path.last().unwrap().id,new_answer);assert_eq!(view.path.last().unwrap().metadata.model.as_deref(),Some("mock-new"));assert_eq!(s.ai_details(&conv,&old_answer).unwrap()["sources"][0]["text"],"旧源");
}
#[test]fn chat_view_second_edit_followup_old_version_memory_and_cold_reopen(){
 let(mut s,root,_,rev,conv)=fixture();let(u1,a1)=turn(&mut s,&conv,&rev,"第一轮",None,None);let(u2,a2)=turn(&mut s,&conv,&rev,"第二轮",Some(&a1),None);let(u3,a3)=turn(&mut s,&conv,&rev,"旧分支后续",Some(&a2),None);
 let(u2v2,a2v2)=turn(&mut s,&conv,&rev,"第二轮修改一",None,Some(&u2));let(u3v2,a3v2)=turn(&mut s,&conv,&rev,"修改一后续",Some(&a2v2),None);
 let(u2v3,a2v3)=turn(&mut s,&conv,&rev,"第二轮修改二",None,Some(&u2v2));let(u3v3,a3v3)=turn(&mut s,&conv,&rev,"修改二后续",Some(&a2v3),None);
 assert_eq!(path(&s,&conv),vec![u1.clone(),a1.clone(),u2v3.clone(),a2v3,u3v3,a3v3.clone()]);let view=s.chat_view(&conv).unwrap();assert_eq!(view.sessions.len(),1);assert_eq!(view.session_id.as_deref(),Some(u1.as_str()));let version=view.versions.iter().find(|v|v.message_id==u2v3).unwrap();assert_eq!((version.index,version.total),(3,3));assert_eq!(version.previous_id.as_deref(),Some(u2v2.as_str()));assert!(version.next_id.is_none());
 s.chat_select(&conv,Some(&u2v2)).unwrap();assert_eq!(path(&s,&conv),vec![u1.clone(),a1.clone(),u2v2.clone(),a2v2,u3v2,a3v2.clone()]);s.chat_select(&conv,Some(&u2)).unwrap();assert_eq!(path(&s,&conv),vec![u1.clone(),a1,u2.clone(),a2,u3,a3.clone()]);
 drop(s);let mut s=Store::open_synthetic(&root,16384).unwrap();assert_eq!(s.chat_view(&conv).unwrap().leaf_id.as_deref(),Some(a3.as_str()));s.chat_select(&conv,Some(&u2v3)).unwrap();assert_eq!(s.chat_view(&conv).unwrap().leaf_id.as_deref(),Some(a3v3.as_str()));assert_eq!(s.chat_view(&conv).unwrap().sessions[0].leaf_id,a3v3);
 s.chat_select(&conv,None).unwrap();drop(s);let s=Store::open_synthetic(&root,16384).unwrap();let view=s.chat_view(&conv).unwrap();assert!(view.path.is_empty());assert!(view.session_id.is_none());assert_eq!(view.sessions.len(),1);
}
#[test]fn chat_view_root_edits_stay_in_session_and_assistant_siblings_are_versions(){
 let(mut s,_,_,rev,conv)=fixture();let(u1,a1)=turn(&mut s,&conv,&rev,"原始根",None,None);let(u1v2,a1v2)=turn(&mut s,&conv,&rev,"根修改一",None,Some(&u1));let(u1v3,a1v3)=turn(&mut s,&conv,&rev,"根修改二",None,Some(&u1v2));assert_eq!(s.chat_view(&conv).unwrap().sessions.len(),1);assert_eq!(s.chat_view(&conv).unwrap().session_id.as_deref(),Some(u1.as_str()));assert_eq!(path(&s,&conv),vec![u1v3,a1v3]);
 let meta=metadata();let alternative=s.message(&conv,&rev,Some(&u1),"另一合成回复",true,&meta).unwrap();s.finish(&alternative,"complete").unwrap();s.chat_select(&conv,Some(&alternative)).unwrap();let view=s.chat_view(&conv).unwrap();let version=view.versions.iter().find(|v|v.message_id==alternative).unwrap();assert_eq!((version.index,version.total),(2,2));assert_eq!(version.previous_id.as_deref(),Some(a1.as_str()));s.chat_select(&conv,Some(&u1v2)).unwrap();assert_eq!(path(&s,&conv),vec![u1v2,a1v2]);
 let(other,_)=turn(&mut s,&conv,&rev,"独立新会话",None,None);assert_eq!(s.chat_view(&conv).unwrap().sessions.len(),2);assert_eq!(s.chat_view(&conv).unwrap().session_id.as_deref(),Some(other.as_str()));
}
#[test]fn chat_view_archive_restore_blocks_continuation_and_keeps_other_document(){
 let(mut s,root,_,rev,conv)=fixture();let(first,answer)=turn(&mut s,&conv,&rev,"将归档",None,None);let(second,second_answer)=turn(&mut s,&conv,&rev,"保留会话",None,None);let(doc2,rev2)=s.create_document("other-chat",&"b".repeat(64),2,"另文档.pdf").unwrap();let conv2=s.local_conversation(&doc2).unwrap();turn(&mut s,&conv2,&rev2,"另一文档记录",None,None);let other=serde_json::to_string(&s.chat_view(&conv2).unwrap()).unwrap();
 s.chat_select(&conv,Some(&answer)).unwrap();let view=s.chat_archive(&conv,&first,true).unwrap();assert_eq!(view.session_id.as_deref(),Some(second.as_str()));assert!(view.sessions.iter().find(|x|x.id==first).unwrap().archived);assert!(s.chat_select(&conv,Some(&answer)).is_err());assert!(s.ai_ancestry(&conv,Some(&answer),&[]).is_err());assert!(s.ai_begin(&conv,&rev,"拒绝归档续问",Some(&answer),None,&metadata(),"[]",1).is_err());assert!(s.ai_begin(&conv,&rev,"拒绝归档改问",None,Some(&first),&metadata(),"[]",1).is_err());assert_eq!(path(&s,&conv),vec![second,second_answer]);
 drop(s);let mut s=Store::open_synthetic(&root,16384).unwrap();assert!(s.chat_view(&conv).unwrap().sessions.iter().find(|x|x.id==first).unwrap().archived);s.chat_archive(&conv,&first,false).unwrap();s.chat_select(&conv,Some(&answer)).unwrap();assert_eq!(s.chat_view(&conv).unwrap().leaf_id.as_deref(),Some(answer.as_str()));assert_eq!(serde_json::to_string(&s.chat_view(&conv2).unwrap()).unwrap(),other);
}
#[test]fn chat_view_session_delete_cleans_complete_family_atomically_and_preserves_pdf_drafts_and_other_history(){
 let(mut s,root,doc,rev,conv)=fixture();let(first,answer)=turn(&mut s,&conv,&rev,"targetDeleteToken",None,None);let(edit,edited_answer)=turn(&mut s,&conv,&rev,"targetDeleteToken edited",None,Some(&first));turn(&mut s,&conv,&rev,"targetDeleteToken following",Some(&edited_answer),None);let(keep,keep_answer)=turn(&mut s,&conv,&rev,"keepToken",None,None);
 let(other_doc,other_rev)=s.create_document("other-delete",&"b".repeat(64),2,"other.pdf").unwrap();let other_conv=s.local_conversation(&other_doc).unwrap();let(other_root,_)=turn(&mut s,&other_conv,&other_rev,"otherToken",None,None);let other=serde_json::to_string(&s.chat_view(&other_conv).unwrap()).unwrap();let draft=uuid();s.put_local_draft(&doc,&rev,&draft,r#"{"schema":1,"pdfjs":"6.4.299","entries":[]}"#).unwrap();let recovery=s.recovery_put(b"important recovery").unwrap();let backup=s.backup("manual",None).unwrap();let backup_bytes=fs::read(&backup).unwrap();let pdf=root.join("disposable.pdf");fs::write(&pdf,b"%PDF-1.7\nuntouched synthetic").unwrap();let pdf_bytes=fs::read(&pdf).unwrap();
 let before=maintenance::logical_digest(&s.conn).unwrap();assert!(s.chat_delete(&conv,&other_root).is_err());assert_eq!(maintenance::logical_digest(&s.conn).unwrap(),before);assert!(s.chat_delete_interrupted(&conv,&first).is_err());assert_eq!(maintenance::logical_digest(&s.conn).unwrap(),before);
 assert_eq!(s.chat_delete(&conv,&first).unwrap(),6);assert_eq!(path(&s,&conv),vec![keep.clone(),keep_answer.clone()]);assert_eq!(s.chat_view(&conv).unwrap().sessions.len(),1);assert!(s.search("targetDeleteToken").unwrap().is_empty());assert!(!s.search("keepToken").unwrap().is_empty());assert_eq!(serde_json::to_string(&s.chat_view(&other_conv).unwrap()).unwrap(),other);
 for id in [first,answer,edit,edited_answer]{assert_eq!(s.conn.query_row("SELECT count(*) FROM data_meta WHERE key IN(?1,?2,?3)",params![format!("ai-context:{id}"),format!("ai-usage:{id}"),format!("message-hidden:{id}")],|r|r.get::<_,i64>(0)).unwrap(),0);}assert_eq!(s.local_drafts(&doc,&rev).unwrap()[0].id,draft);assert_eq!(s.recovery_get(&recovery).unwrap(),b"important recovery");assert_eq!(fs::read(&backup).unwrap(),backup_bytes);assert_eq!(fs::read(&pdf).unwrap(),pdf_bytes);s.check().unwrap();
 s.delete_document_history(&doc,&conv).unwrap();assert!(s.chat_view(&conv).unwrap().sessions.is_empty());assert_eq!(s.conn.query_row("SELECT count(*) FROM data_meta WHERE key=?1",[key(&conv)],|r|r.get::<_,i64>(0)).unwrap(),0);assert_eq!(serde_json::to_string(&s.chat_view(&other_conv).unwrap()).unwrap(),other);
}
#[test]fn chat_view_full_path_exceeds_old_preview_and_never_truncates_message_text(){
 let(mut s,_,_,rev,conv)=fixture();let mut parent=None;let mut expected=Vec::new();for n in 0..60{let(u,a)=turn(&mut s,&conv,&rev,&format!("轮 {n}"),parent.as_deref(),None);expected.extend([u,a.clone()]);parent=Some(a);}let leaf=parent.unwrap();s.conn.execute("UPDATE messages SET content=?1 WHERE id=?2",params!["x".repeat(20000),leaf]).unwrap();let view=s.chat_view(&conv).unwrap();assert_eq!(view.path.iter().map(|m|m.id.clone()).collect::<Vec<_>>(),expected);assert_eq!(view.path.len(),120);assert_eq!(view.path.last().unwrap().content.len(),20000);assert!(view.path.iter().all(|m|!m.truncated));
}
#[test]fn chat_view_node_growth_and_future_metadata_are_rejected_without_write(){
 let(mut s,_,doc,rev,conv)=fixture();{let tx=s.conn.transaction().unwrap();for n in 0..4095{tx.execute("INSERT INTO messages(id,conversation_id,document_id,revision_id,role,status,content,metadata,created_ms) VALUES(?1,?2,?3,?4,'user','complete',?5,'{}',0)",params![uuid(),conv,doc,rev,format!("synthetic {n}")]).unwrap();}tx.commit().unwrap();}
 let before=maintenance::logical_digest(&s.conn).unwrap();assert!(matches!(s.ai_begin(&conv,&rev,"two nodes overflow",None,None,&metadata(),"[]",1),Err(DataError::Refused("chat node budget"))));assert_eq!(maintenance::logical_digest(&s.conn).unwrap(),before);assert_eq!(s.chat_view(&conv).unwrap().sessions.len(),4095);
 s.conn.execute("INSERT INTO data_meta VALUES(?1,?2)",params![key(&conv),r#"{"schemaVersion":99,"generation":0,"activeSession":null,"activeLeaf":null,"archived":[],"remembered":{},"sessionLeaves":{}}"#]).unwrap();let before=maintenance::logical_digest(&s.conn).unwrap();assert!(s.chat_view(&conv).is_err());assert!(s.chat_select(&conv,None).is_err());assert_eq!(maintenance::logical_digest(&s.conn).unwrap(),before);
}
